    { word: "tea", phonetic: "/tiː/", def: "A hot or cold drink made by infusing dried leaves.", defVn: "trà, chè", pos: "noun", ex: ["Green tea is great for your skin and heart.", "Vietnamese iced tea is popular in street stalls."], exVn: ["Trà xanh rất tốt cho làn da và tim mạch.", "Trà đá vỉa hè rất phổ biến ở Việt Nam."] },
    { word: "coffee", phonetic: "/ˈkɔːfi/", def: "A dark hot drink made from roasted coffee beans.", defVn: "cà phê", pos: "noun", ex: ["Vietnamese iced milk coffee is rich and sweet.", "I drink a cup of black coffee every morning."], exVn: ["Cà phê sữa đá Việt Nam đậm đà và ngọt ngào.", "Tôi uống một tách cà phê đen mỗi sáng."] },
    { word: "juice", phonetic: "/dʒuːs/", def: "Liquid extracted from fruit or vegetables.", defVn: "nước ép hoa quả", pos: "noun", ex: ["Fresh orange juice is rich in vitamin C.", "Watermelon juice is very refreshing in summer."], exVn: ["Nước cam tươi rất giàu vitamin C.", "Nước ép dưa hấu rất thanh mát vào mùa hè."] },
    { word: "cheese", phonetic: "/tʃiːz/", def: "Food made from the pressed curds of milk.", defVn: "phô mai", pos: "noun", ex: ["Melted cheese makes pizza taste incredible.", "He loves cheese with crackers."], exVn: ["Phô mai tan chảy làm bánh pizza ngon tuyệt vời.", "Anh ấy thích ăn phô mai với bánh quy giòn."] },
    { word: "butter", phonetic: "/ˈbʌtər/", def: "Pale yellow fatty food substance made from cream.", defVn: "bơ (bơ sữa thực phẩm)", pos: "noun", ex: ["Spread butter evenly on warm toast.", "Garlic butter bread smells amazing."], exVn: ["Phết bơ đều lên bánh mì nướng nóng.", "Bánh mì bơ tỏi tỏa mùi thơm ngát."] },
    { word: "salt", phonetic: "/sɔːlt/", def: "White crystalline substance used for seasoning.", defVn: "muối ăn", pos: "noun", ex: ["Add a pinch of salt to balance the flavor.", "Do not eat too much salt for blood pressure."], exVn: ["Thêm một nhúm muối để cân bằng hương vị.", "Đừng ăn quá nhiều muối để bảo vệ huyết áp."] },
    { word: "sugar", phonetic: "/ˈʃʊɡər/", def: "Sweet substance obtained from sugar cane.", defVn: "đường ăn", pos: "noun", ex: ["I take my coffee with no sugar.", "Too much sugar is not good for your teeth."], exVn: ["Tôi uống cà phê không đường.", "Quá nhiều đường không tốt cho răng của bạn."] },
    { word: "sauce", phonetic: "/sɔːs/", def: "Liquid condiment served with food to add flavor.", defVn: "nước sốt, nước chấm", pos: "noun", ex: ["Fish sauce is the soul of Vietnamese cuisine.", "Dip spring rolls into sweet and sour sauce."], exVn: ["Nước mắm là linh hồn của ẩm thực Việt Nam.", "Chấm nem rán vào nước sốt chua ngọt."] },
    { word: "snack", phonetic: "/snæk/", def: "A small amount of food eaten between meals.", defVn: "đồ ăn vặt, bữa ăn nhẹ", pos: "noun", ex: ["Nuts and dried fruits are healthy snacks.", "I grab a quick snack before my gym workout."], exVn: ["Các loại hạt và hoa quả sấy là đồ ăn vặt lành mạnh.", "Tôi ăn nhẹ một chút trước khi đi tập thể hình."] },
    { word: "dessert", phonetic: "/dɪˈzɜːrt/", def: "Sweet food eaten at the end of a meal.", defVn: "món tráng miệng", pos: "noun", ex: ["We had vanilla ice cream for dessert.", "Fruit pudding is my favorite dessert."], exVn: ["Chúng tôi ăn kem vani làm món tráng miệng.", "Chè hoa quả là món tráng miệng yêu thích của tôi."] },
    { word: "cake", phonetic: "/keɪk/", def: "Sweet baked food made from flour, sugar, eggs.", defVn: "bánh ngọt, bánh sinh nhật", pos: "noun", ex: ["She baked a chocolate cake for his birthday.", "A slice of strawberry cake with tea."], exVn: ["Cô ấy đã nướng một chiếc bánh sô-cô-la cho sinh nhật.", "Một lát bánh dâu tây cùng với trà."] },
    { word: "ice cream", phonetic: "/ˈaɪs kriːm/", def: "Frozen sweet food made from cream and milk.", defVn: "kem lạnh, cây kem", pos: "noun", ex: ["Eating cool ice cream on a sunny summer day.", "Which flavor do you like: matcha or chocolate?"], exVn: ["Ăn kem mát lạnh trong ngày hè ngập nắng.", "Bạn thích vị nào: trà xanh hay sô-cô-la?"] },
    { word: "delicious", phonetic: "/dɪˈlɪʃəs/", def: "Having a very pleasant taste.", defVn: "ngon miệng, thơm ngon", pos: "adj", ex: ["This homemade pho is truly delicious.", "Thank you for the delicious dinner!"], exVn: ["Món phở nhà nấu này thực sự thơm ngon.", "Cảm ơn bạn vì bữa tối ngon miệng!"] },
    { word: "hungry", phonetic: "/ˈhʌŋɡri/", def: "Feeling a need or desire for food.", defVn: "đói bụng", pos: "adj", ex: ["I am starving hungry after school.", "Are you hungry? Let's get something to eat."], exVn: ["Tôi đói cồn cào sau giờ học.", "Bạn đói không? Hãy đi kiếm gì đó ăn nào."] },
    { word: "thirsty", phonetic: "/ˈθɜːrsti/", def: "Feeling a need to drink liquid.", defVn: "khát nước", pos: "adj", ex: ["Running in the sun makes me very thirsty.", "Drink fresh water whenever you feel thirsty."], exVn: ["Chạy dưới trời nắng làm tôi rất khát nước.", "Hãy uống nước lọc bất cứ khi nào bạn thấy khát."] },
    { word: "full", phonetic: "/fʊl/", def: "Having had enough to eat or drink.", defVn: "no bụng, đã no", pos: "adj", ex: ["I cannot eat anymore, I am completely full.", "The delicious meal left everyone satisfied and full."], exVn: ["Tôi không thể ăn thêm được nữa, tôi no căng rồi.", "Bữa ăn ngon làm ai nấy đều thỏa mãn và no nê."] },
    { word: "spicy", phonetic: "/ˈspaɪsi/", def: "Flavored with or fragrant with spice; hot.", defVn: "cay nồng", pos: "adj", ex: ["Do you like spicy food with lots of chili?", "This Korean kimchi soup is very spicy."], exVn: ["Bạn có thích ăn cay với nhiều ớt không?", "Món canh kim chi Hàn Quốc này rất cay nồng."] },
    { word: "sweet", phonetic: "/swiːt/", def: "Having the pleasant taste of sugar or honey.", defVn: "ngọt ngào, có vị ngọt", pos: "adj", ex: ["Ripe mangoes are naturally sweet and fragrant.", "This milk tea is sweet and refreshing."], exVn: ["Xoài chín có vị ngọt tự nhiên và thơm nức.", "Trà sữa này ngọt ngào và sảng khoái."] },
    { word: "sour", phonetic: "/ˈsaʊər/", def: "Having an acid taste like lemon or vinegar.", defVn: "chua", pos: "adj", ex: ["Fresh lemon juice is very sour without sugar.", "Green mango with chili salt is delightfully sour."], exVn: ["Nước chanh tươi rất chua nếu không cho đường.", "Xoài xanh chấm muối ớt có vị chua hấp dẫn."] },
    { word: "salty", phonetic: "/ˈsɔːlti/", def: "Tasting of or containing salt.", defVn: "mặn, có vị mặn", pos: "adj", ex: ["The soup is a little bit too salty.", "Sea water is very salty."], exVn: ["Món súp hơi có vị mặn một chút.", "Nước biển rất mặn."] },
    { word: "bitter", phonetic: "/ˈbɪtər/", def: "Having a sharp, pungent taste like dark chocolate.", defVn: "đắng", pos: "adj", ex: ["Bitter melon is famous for cooling the body.", "Pure dark coffee has a pleasant bitter note."], exVn: ["Mướp đắng nổi tiếng với công dụng thanh nhiệt.", "Cà phê đen nguyên chất có vị đắng nhẹ dễ chịu."] },
    { word: "fresh", phonetic: "/freʃ/", def: "Recently made or gathered; not stale.", defVn: "tươi mới, tươi ngon", pos: "adj", ex: ["We always buy fresh herbs at the local market.", "Fresh fruits are delivered every morning."], exVn: ["Chúng tôi luôn mua rau thơm tươi tại chợ địa phương.", "Hoa quả tươi được giao đến mỗi sáng sớm."] }
